/** Illustrative, interactive evidence views for the Episode 3–5 arc.
 * dispatch receives the existing choice ID string; reducer validates prerequisites.
 * These graphics are interpretation, not a depiction of exact canonical artifacts. */
const NS='http://www.w3.org/2000/svg';
const el=(name,cls)=>{const e=document.createElement(name);if(cls)e.className=cls;return e;};
const svg=()=>{const e=document.createElementNS(NS,'svg');e.setAttribute('viewBox','0 0 360 150');e.setAttribute('role','img');return e;};
const shape=(name,attrs,parent)=>{const n=document.createElementNS(NS,name);for(const [k,v] of Object.entries(attrs))n.setAttribute(k,String(v));parent.append(n);return n;};
function wrap(label){const w=el('div','arc35-visual');w.setAttribute('aria-label',label);w.style.cssText='margin:.7rem 0; border:1px solid #70949a; border-radius:.7rem; overflow:hidden;background:#071d2b;';return w;}
function action(w,text,fn){const b=el('button','secondary');b.type='button';b.textContent=text;b.style.cssText='margin:.4rem;min-height:48px';b.onclick=fn;w.append(b);}
function caption(w,text){const p=el('p');p.textContent=text;p.style.cssText='font-size:.8rem;margin:.35rem .6rem;color:#c8dcda';w.append(p);}
function motif(group,stroke){shape('path',{d:'M0 -28 L0 5 M0 5 L-26 24 M0 5 L27 19 M0 5 L4 31 M-24 -23 A34 34 0 1 0 13 -31',fill:'none',stroke,'stroke-width':3,'stroke-linecap':'round','stroke-linejoin':'round'},group);}
function waterView(id){const w=wrap('Illustrative canal reflection at '+(id==='near_view'?'the steps':'the overlook'));const pic=svg();pic.setAttribute('aria-label','Barge reflection moves across water; its lines remain visible for comparison');shape('rect',{width:360,height:150,fill:'#0b3749'},pic);for(let y=65;y<150;y+=14)shape('path',{d:`M0 ${y} Q90 ${y-5} 180 ${y} T360 ${y}`,fill:'none',stroke:'#64bed0','stroke-width':1,opacity:.38},pic);const st=shape('style',{},pic);st.textContent='@keyframes arc35Drift{from{transform:translateX(-9px)}to{transform:translateX(9px)}} .arc35-drift{animation:arc35Drift 7s ease-in-out infinite alternate} @media(prefers-reduced-motion:reduce){.arc35-drift{animation:none}}';const moving=shape('g',{class:'arc35-drift'},pic);shape('path',{d:id==='near_view'?'M48 32h100l-17 18H66z':'M198 32h100l-17 18H216z',fill:'#b28c54'},moving);const g=shape('g',{transform:id==='near_view'?'translate(95 96) rotate(8) scale(.8 .7)':'translate(245 96) rotate(-8) scale(.8 .7)'},moving);motif(g,'#9be9ed');w.append(pic);caption(w,'Illustrative water observation: the passing barge and your position change the view.');return w;}
function chartView(){const w=wrap('Kaelan’s illustrative temple sketch');const pic=svg();pic.setAttribute('aria-label','A branching shape and interrupted ring drawn in a notebook');shape('rect',{width:360,height:150,fill:'#c9b99a'},pic);for(let y=20;y<150;y+=20)shape('path',{d:`M20 ${y}H340`,stroke:'#857d6a',opacity:.2},pic);const g=shape('g',{transform:'translate(180 75)'},pic);motif(g,'#4c4135');w.append(pic);caption(w,'The temple sketch stays available as a reference.');return w;}
function dragSurface(w,label,onCommit,revealed=false){const s=el('div');s.setAttribute('role','group');s.setAttribute('aria-label',label);s.style.cssText='position:relative;height:128px;touch-action:none;overflow:hidden;cursor:grab;background:linear-gradient(140deg,#82694d,#493a2d);';let pointer=null,start=0;const cover=el('div');cover.style.cssText='position:absolute;inset:0 38% 0 0;background:repeating-linear-gradient(90deg,#72513b,#967357 15px,#72513b 30px);box-shadow:4px 0 8px #0006';const mark=svg();mark.setAttribute('viewBox','-45 -45 90 90');mark.setAttribute('aria-label','Branching markings beneath the covering');motif(mark,'#b9edec');mark.style.cssText='position:absolute;left:40%;top:18%;width:80px;height:80px;filter:drop-shadow(0 0 8px #63c9d1)';const t=el('div');t.textContent='Drag the covering aside';t.style.cssText='position:absolute;left:.6rem;bottom:.4rem;color:#fff3d8;font-size:.83rem;text-shadow:0 1px 4px black';s.append(mark,cover,t);if(revealed){cover.style.transform='translateX(-115%)';t.textContent='The reflected markings are exposed';}s.onpointerdown=e=>{pointer=e.pointerId;start=e.clientX;s.setPointerCapture(pointer);};s.onpointermove=e=>{if(e.pointerId!==pointer)return;const delta=Math.max(0,Math.min(110,e.clientX-start));cover.style.transform=`translateX(${-delta}px)`;};const end=e=>{if(e.pointerId!==pointer)return;const delta=e.clientX-start;pointer=null;if(delta>55)onCommit();else cover.style.transform='';};s.onpointerup=end;s.onpointercancel=s.onlostpointercapture=()=>{pointer=null;cover.style.transform=revealed?'translateX(-115%)':'';};w.cancelInteraction=()=>{const old=pointer;pointer=null;try{if(old!==null&&s.hasPointerCapture(old))s.releasePointerCapture(old);}catch{}cover.style.transform=revealed?'translateX(-115%)':'';};w.append(s);}
function wallView(dispatch,state){const revealed=state?.flags?.wall_revealed===true,w=wrap('Workshop wall with movable covering');w.setAttribute('data-revealed',String(revealed));dragSurface(w,'Drag the wall covering to one side',()=>dispatch('expose'),revealed);if(!revealed)action(w,'Move the covering aside',()=>dispatch('expose'));caption(w,revealed?'The reflected markings are visible beneath the old covering.':'Changing the surface exposes what the reflected light reaches.');return w;}
function lampView(dispatch,state){const revealed=state?.flags?.crystal_ink===true,w=wrap('Hidden ledger and movable lamp');w.setAttribute('data-ink-visible',String(revealed));const s=el('div');s.setAttribute('role','group');s.setAttribute('aria-label','Move the lamp toward the side of the ledger');s.style.cssText='height:130px;position:relative;touch-action:none;overflow:hidden;cursor:grab;background:linear-gradient(#142e3a,#493b30)';const paper=el('div');paper.style.cssText='position:absolute;left:17%;right:17%;top:42%;height:44%;background:#c7b899;transform:perspective(300px) rotateX(28deg);box-shadow:0 4px 8px #0008';const lamp=el('div');lamp.textContent='✦';lamp.style.cssText='position:absolute;left:48%;top:5%;font-size:2rem;color:#fce3a0;text-shadow:0 0 20px #ffcc6a';const instruction=el('div');instruction.textContent='Drag the lamp toward the edge';instruction.style.cssText='position:absolute;bottom:.25rem;left:.6rem;font-size:.8rem;color:#fff4d2';if(revealed){const ink=svg();ink.setAttribute('aria-label','Previously hidden branching ink visible in grazing light');ink.setAttribute('data-crystal-ink','visible');ink.style.cssText='width:100%;height:100%;display:block';const inkMark=shape('g',{transform:'translate(180 78) scale(.7)'},ink);motif(inkMark,'#45767d');paper.append(ink);lamp.style.transform='translateX(-100px)';instruction.textContent='Crystal ink emerges in grazing light';}s.append(paper,lamp,instruction);let pointer=null,start=0; s.onpointerdown=e=>{pointer=e.pointerId;start=e.clientX;s.setPointerCapture(pointer);};s.onpointermove=e=>{if(pointer!==e.pointerId)return;const dx=Math.max(-110,Math.min(110,e.clientX-start));lamp.style.transform=`translateX(${dx}px)`;};s.onpointerup=e=>{if(pointer!==e.pointerId)return;const delta=Math.abs(e.clientX-start);pointer=null;if(delta>55)dispatch('oblique');else lamp.style.transform='';};s.onpointercancel=s.onlostpointercapture=()=>{pointer=null;lamp.style.transform=revealed?'translateX(-100px)':'';};w.cancelInteraction=()=>{const old=pointer;pointer=null;try{if(old!==null&&s.hasPointerCapture(old))s.releasePointerCapture(old);}catch{}lamp.style.transform=revealed?'translateX(-100px)':'';};w.append(s);if(!revealed)action(w,'Move lamp to the side',()=>dispatch('oblique'));caption(w,revealed?'The previously hidden ink is visible.':'Compare direct light with a grazing angle across the page.');return w;}
export function makeArc35Visual(sceneId,objectId,dispatch,state){if(typeof dispatch!=='function')throw new TypeError('dispatch callback required');if(sceneId==='canal'&&(objectId==='near_view'||objectId==='far_view'))return waterView(objectId);if(sceneId==='canal'&&objectId==='chart')return chartView();if(sceneId==='workshop'&&objectId==='old_wall')return wallView(dispatch,state);if(sceneId==='archive'&&objectId==='lamp')return lampView(dispatch,state);return null;}
